import java.util.Arrays;

interface DisjointSet {
    int find(int i);
    void union(int i, int j);
    boolean connected(int i, int j);
    int size();
    int count();
}

public class UnionFind implements DisjointSet {
    private final int[] parent;
    private final int[] rank;
    private int count;

    public UnionFind(int size) {

        parent = new int[size];
        rank = new int[size];
        count = size;
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    private void validate(int i) {
        if (i < 0 || i >= parent.length) {
            throw new IllegalArgumentException("Index " + i + " out of bounds for size " + parent.length);
        }
    }

    public int find(int i) {
        validate(i);

        if (parent[i] != i) {
            parent[i] = find(parent[i]);
        }

        return parent[i];
    }

    public void union(int i, int j) {
        validate(i);
        validate(j);

        int irep = find(i);

        int jrep = find(j);

        if (irep == jrep) return;

        count--;

        if (rank[irep] < rank[jrep]) {
            parent[irep] = jrep;
        } else if (rank[irep] > rank[jrep]) {
            parent[jrep] = irep;
        } else {
            parent[jrep] = irep;
            rank[irep]++;
        }
    }

    public int size() {
        return parent.length;
    }

    public int count() {
        return count;
    }

    public boolean connected(int i, int j) {
        validate(i);
        validate(j);
        return find(i) == find(j);
    }

    public static void main(String[] args) {
        int size = 5;
        DisjointSet uf = new UnionFind(size);
        uf.union(1, 2);
        uf.union(3, 4);
        System.out.println("Are 1 and 2 in the same set? " + uf.connected(1, 2));
    }
}

